Object.assign(SNIP,{});PRESET_NOTES["l68"]={"Ví dụ: So khớp trâu bò": "Mỗi vị trí bắt đầu so từ đầu mẫu. Trường hợp xấu t = aaaa…a, p = aa…ab: mỗi vị trí so gần hết m ký tự, tổng O(n · m).", "Ví dụ: Hàm tiền tố": "Tại i = 5 (a): k = π[4] = 2, s[5] = a ≠ s[2] = b nên lùi k = π[1] = 1; lúc này s[5] = s[1] = a nên π[5] = 2. Tại i = 6 (b): k = 2, s[6] = s[2] = b nên π[6] = 3 — “aab” vừa là tiền tố vừa là hậu tố.", "Ví dụ: KMP tìm mọi vị trí": "Các lần xuất hiện có thể chồng lên nhau (0 và 2). Con trỏ i trên văn bản không bao giờ lùi lại.", "Ví dụ: Z-function": "z của “aabxaab”: 0 1 0 0 3 1 0 (z[0] quy ước 0; z[4] = 3 vì “aab” lặp lại). Tìm “ab” trong “cabcab”: các vị trí 1 và 4.", "Lỗi: không khớp thì quay về đầu mẫu": "In 0. Khi đọc ký tự a thứ ba, đã khớp “aa” nhưng cần b; quay về 0 rồi khớp lại chỉ còn “a”, bỏ mất khả năng “aa” (hai ký tự cuối) vẫn là tiền tố của mẫu. π[1] = 1 cho biết phải giữ lại 1 ký tự đã khớp."};EX_HINTS["l68"]=[["Tính π của p. Chạy k trên t: khi t[i] ≠ p[k] thì lùi k = π[k − 1] (lặp), khớp thì k++.", "Khi k = |p|: một lần xuất hiện kết thúc tại i, bắt đầu tại i − |p| + 1 (cộng 1 nữa vì đánh số từ 1); rồi k = π[k − 1] để đếm cả các lần chồng nhau.", "Thử từng vị trí rồi so cả mẫu tốn O(|t| · |p|) với t = aaa…a, p = aa…ab."], ["s có chu kỳ d ⇔ tiền tố độ dài n − d trùng hậu tố độ dài n − d.", "Muốn d nhỏ nhất thì cần đoạn trùng (tiền tố = hậu tố) dài nhất: π[n − 1]. Đáp án n − π[n − 1].", "Thử từng d rồi kiểm tra cả chuỗi tốn O(n²) với s = aaa…ab."], ["b là phép xoay trái k nấc của a ⇔ b xuất hiện trong a + a tại vị trí k.", "Tìm lần xuất hiện đầu tiên của b trong a + a (chỉ xét k < |a|) bằng Z-function của b + '#' + a + a, hoặc bằng KMP.", "Thử từng k rồi so cả chuỗi tốn O(n²) với a = aa…ab, b = aa…a."]];
/* ===================== BÀI 68 · So khớp chuỗi: KMP và Z-function ===================== */
/* Bài 68 · So khớp chuỗi: KMP và Z-function
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR68=[{label:"Ví dụ: So khớp trâu bò",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string t = \"abababcab\", p = \"abc\";\n    int n = t.size(), m = p.size(), soSanh = 0;\n    for (int i = 0; i + m <= n; i++) {\n        int j = 0;\n        while (j < m && t[i + j] == p[j]) { j++; soSanh++; }   // thử đặt p tại vị trí i\n        if (j < m) soSanh++;\n        if (j == m) cout << \"gap tai \" << i << \"\\n\";\n    }\n    cout << soSanh << \" lan so sanh\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["i","j","soSanh"]}],py:{code:"t, p = \"abababcab\", \"abc\"\nn, m = len(t), len(p)\nso_sanh = 0\nfor i in range(n - m + 1):\n    j = 0\n    while j < m and t[i + j] == p[j]:  # thử đặt p tại vị trí i\n        j += 1\n        so_sanh += 1\n    if j < m:\n        so_sanh += 1\n    if j == m:\n        print(\"gap tai\", i)\nprint(so_sanh, \"lan so sanh\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string t = \"abababcab\", p = \"abc\";\n        int n = t.Length, m = p.Length, soSanh = 0;\n        for (int i = 0; i + m <= n; i++)\n        {\n            int j = 0;\n            while (j < m && t[i + j] == p[j]) { j++; soSanh++; }   // thử đặt p tại vị trí i\n            if (j < m) soSanh++;\n            if (j == m) Console.WriteLine(\"gap tai \" + i);\n        }\n        Console.WriteLine(soSanh + \" lan so sanh\");\n    }\n}"}},{label:"Ví dụ: Hàm tiền tố",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = \"aabaaab\";\n    int n = s.size();\n    vector<int> pi(n, 0);\n    for (int i = 1; i < n; i++) {\n        int k = pi[i - 1];\n        while (k > 0 && s[i] != s[k]) k = pi[k - 1];   // lùi về đoạn khớp ngắn hơn\n        if (s[i] == s[k]) k++;\n        pi[i] = k;\n    }\n    for (int x : pi) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"pi",ptr:["i","k"]},{type:"vars",names:["s","i","k"]}],py:{code:"s = \"aabaaab\"\nn = len(s)\npi = [0] * n\nfor i in range(1, n):\n    k = pi[i - 1]\n    while k > 0 and s[i] != s[k]:      # lùi về đoạn khớp ngắn hơn\n        k = pi[k - 1]\n    if s[i] == s[k]:\n        k += 1\n    pi[i] = k\nprint(*pi)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = \"aabaaab\";\n        int n = s.Length;\n        int[] pi = new int[n];\n        for (int i = 1; i < n; i++)\n        {\n            int k = pi[i - 1];\n            while (k > 0 && s[i] != s[k]) k = pi[k - 1];   // lùi về đoạn khớp ngắn hơn\n            if (s[i] == s[k]) k++;\n            pi[i] = k;\n        }\n        Console.WriteLine(string.Join(\" \", pi));\n    }\n}"}},{label:"Ví dụ: KMP tìm mọi vị trí",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvector<int> tienTo(const string& s) {  // hàm tiền tố π\n    int n = s.size();\n    vector<int> pi(n, 0);\n    for (int i = 1; i < n; i++) {\n        int k = pi[i - 1];\n        while (k > 0 && s[i] != s[k]) k = pi[k - 1];   // lùi về đoạn khớp ngắn hơn\n        if (s[i] == s[k]) k++;\n        pi[i] = k;\n    }\n    return pi;\n}\n\nint main() {\n    string t = \"abababcabababab\", p = \"abab\";\n    vector<int> pi = tienTo(p);\n    int k = 0, m = p.size();\n    for (int i = 0; i < (int)t.size(); i++) {\n        while (k > 0 && t[i] != p[k]) k = pi[k - 1];\n        if (t[i] == p[k]) k++;\n        if (k == m) {                  // khớp trọn mẫu, kết thúc tại i\n            cout << i - m + 1 << \" \";\n            k = pi[k - 1];             // tìm tiếp, cho phép các lần xuất hiện chồng nhau\n        }\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"pi",ptr:["k"]},{type:"vars",names:["i","k"]}],py:{code:"def tien_to(s):                        # hàm tiền tố π\n    pi = [0] * len(s)\n    for i in range(1, len(s)):\n        k = pi[i - 1]\n        while k > 0 and s[i] != s[k]:  # lùi về đoạn khớp ngắn hơn\n            k = pi[k - 1]\n        if s[i] == s[k]:\n            k += 1\n        pi[i] = k\n    return pi\n\nt, p = \"abababcabababab\", \"abab\"\npi = tien_to(p)\nk, m = 0, len(p)\nkq = []\nfor i in range(len(t)):\n    while k > 0 and t[i] != p[k]:\n        k = pi[k - 1]\n    if t[i] == p[k]:\n        k += 1\n    if k == m:                         # khớp trọn mẫu, kết thúc tại i\n        kq.append(i - m + 1)\n        k = pi[k - 1]                  # tìm tiếp, cho phép chồng nhau\nprint(*kq)"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] TienTo(string s)          // hàm tiền tố π\n    {\n        int n = s.Length;\n        int[] pi = new int[n];\n        for (int i = 1; i < n; i++)\n        {\n            int k = pi[i - 1];\n            while (k > 0 && s[i] != s[k]) k = pi[k - 1];   // lùi về đoạn khớp ngắn hơn\n            if (s[i] == s[k]) k++;\n            pi[i] = k;\n        }\n        return pi;\n    }\n\n    static void Main()\n    {\n        string t = \"abababcabababab\", p = \"abab\";\n        int[] pi = TienTo(p);\n        int k = 0, m = p.Length;\n        for (int i = 0; i < t.Length; i++)\n        {\n            while (k > 0 && t[i] != p[k]) k = pi[k - 1];\n            if (t[i] == p[k]) k++;\n            if (k == m)                        // khớp trọn mẫu, kết thúc tại i\n            {\n                Console.Write((i - m + 1) + \" \");\n                k = pi[k - 1];                 // tìm tiếp, cho phép chồng nhau\n            }\n        }\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: Z-function",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvector<int> hamZ(const string& s) {\n    int n = s.size();\n    vector<int> z(n, 0);\n    int l = 0, r = 0;                  // hộp [l, r) khớp với tiền tố\n    for (int i = 1; i < n; i++) {\n        if (i < r) z[i] = min(r - i, z[i - l]);   // tận dụng phần đã biết\n        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;\n        if (i + z[i] > r) { l = i; r = i + z[i]; }\n    }\n    return z;\n}\n\nint main() {\n    string s = \"aabxaab\";\n    vector<int> z = hamZ(s);\n    for (int x : z) cout << x << \" \";\n    cout << \"\\n\";\n    string p = \"ab\", t = \"cabcab\";\n    vector<int> z2 = hamZ(p + \"#\" + t);   // ghép mẫu, dấu ngăn, văn bản\n    for (int i = p.size() + 1; i < (int)z2.size(); i++)\n        if (z2[i] == (int)p.size()) cout << i - (int)p.size() - 1 << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"z",ptr:["i","l","r"]},{type:"vars",names:["i","l","r"]}],py:{code:"def ham_z(s):\n    n = len(s)\n    z = [0] * n\n    l = r = 0                          # hộp [l, r) khớp với tiền tố\n    for i in range(1, n):\n        if i < r:\n            z[i] = min(r - i, z[i - l])   # tận dụng phần đã biết\n        while i + z[i] < n and s[z[i]] == s[i + z[i]]:\n            z[i] += 1\n        if i + z[i] > r:\n            l, r = i, i + z[i]\n    return z\n\nprint(*ham_z(\"aabxaab\"))\np, t = \"ab\", \"cabcab\"\nz2 = ham_z(p + \"#\" + t)                # ghép mẫu, dấu ngăn, văn bản\nprint(*[i - len(p) - 1 for i in range(len(p) + 1, len(z2)) if z2[i] == len(p)])"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] HamZ(string s)\n    {\n        int n = s.Length;\n        int[] z = new int[n];\n        int l = 0, r = 0;                  // hộp [l, r) khớp với tiền tố\n        for (int i = 1; i < n; i++)\n        {\n            if (i < r) z[i] = Math.Min(r - i, z[i - l]);   // tận dụng phần đã biết\n            while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;\n            if (i + z[i] > r) { l = i; r = i + z[i]; }\n        }\n        return z;\n    }\n\n    static void Main()\n    {\n        int[] z = HamZ(\"aabxaab\");\n        Console.WriteLine(string.Join(\" \", z));\n        string p = \"ab\", t = \"cabcab\";\n        int[] z2 = HamZ(p + \"#\" + t);          // ghép mẫu, dấu ngăn, văn bản\n        for (int i = p.Length + 1; i < z2.Length; i++)\n            if (z2[i] == p.Length) Console.Write((i - p.Length - 1) + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Lỗi: không khớp thì quay về đầu mẫu",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string t = \"aaab\", p = \"aab\";\n    int k = 0, dem = 0, m = p.size();\n    for (int i = 0; i < (int)t.size(); i++) {\n        if (t[i] != p[k]) k = 0;       // SAI: phải lùi k = pi[k - 1], không phải về 0\n        if (t[i] == p[k]) k++;\n        if (k == m) { dem++; k = 0; }\n    }\n    cout << dem << \"\\n\";               // đúng phải là 1 (tại vị trí 1)\n    return 0;\n}",viz:[{type:"vars",names:["i","k","dem"]}],py:{code:"t, p = \"aaab\", \"aab\"\nk = dem = 0\nm = len(p)\nfor i in range(len(t)):\n    if t[i] != p[k]:\n        k = 0                          # SAI: phải lùi k = pi[k - 1], không phải về 0\n    if t[i] == p[k]:\n        k += 1\n    if k == m:\n        dem += 1\n        k = 0\nprint(dem)                             # đúng phải là 1 (tại vị trí 1)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string t = \"aaab\", p = \"aab\";\n        int k = 0, dem = 0, m = p.Length;\n        for (int i = 0; i < t.Length; i++)\n        {\n            if (t[i] != p[k]) k = 0;           // SAI: phải lùi k = pi[k - 1], không phải về 0\n            if (t[i] == p[k]) k++;\n            if (k == m) { dem++; k = 0; }\n        }\n        Console.WriteLine(dem);                // đúng phải là 1 (tại vị trí 1)\n    }\n}"}}];
const sim68=makeSim2(document.getElementById("sim-l68"),{id:"s68",presets:PR68});
makeEx2(document.getElementById("ex-l68"),sim68,[{t:"Tìm từ khóa",d:"Cho văn bản t và từ khóa p (chỉ gồm chữ thường, 1 ≤ |p|, |t| ≤ 10^6). In số lần p xuất hiện trong t (tính cả các lần chồng nhau) và vị trí bắt đầu (đánh số từ 1) của lần đầu tiên, hoặc −1 nếu không có. Đầu vào: dòng t, dòng p. Đầu ra: hai số trên một dòng.",tests:[{in:"abababcabababab\nabab",out:"5 1"},{in:"aaaa\naa",out:"3 1"},{in:"abc\nabcd",out:"0 -1"},{in:"hello\no",out:"1 5"},{in:"aaab\naab",out:"1 2"},{in:"baabbbbbbaaababaaaaaabbbaaabaaabbbaabbbbabbaaabbaaabbbabbbbb\naba",out:"3 12"},{in:"bbaaabababbbaaababababbbbabbbaaabbabbbbabbbaaabbbaaabaabbbaaabbabbaaabbaabbabbbb\naaa",out:"7 3"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string t, p;\n    cin >> t >> p;\n    int dem = 0, dau = -1;\n    // KMP: hàm tiền tố của p rồi chạy trên t\n    cout << dem << \" \" << dau << \"\\n\";\n    return 0;\n}",perf:{gen:n=>"a".repeat(n)+"\n"+"a".repeat(Math.floor(n/2))+"b",ns:[250,500,1000,2000],need:"n",limit:n=>60*n+300,why:"So lại từ đầu mẫu ở mỗi vị trí tốn O(|t| · |p|)."},py:{start:"t = input()\np = input()\ndem, dau = 0, -1\n# KMP: hàm tiền tố của p rồi chạy trên t (không dùng str.find)\nprint(dem, dau)",hints:["Tính π của p. Chạy k trên t: khi t[i] ≠ p[k] thì lùi k = π[k − 1] (lặp), khớp thì k += 1.","Khi k = len(p): một lần xuất hiện bắt đầu tại i − len(p) + 1 (cộng 1 nữa vì đánh số từ 1); rồi k = π[k − 1] để đếm cả các lần chồng nhau.","str.count không đếm các lần chồng nhau; so từng vị trí bằng t[i:i+m] == p tốn O(|t| · |p|)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string t = Console.ReadLine(), p = Console.ReadLine();\n        int dem = 0, dau = -1;\n        // KMP: hàm tiền tố của p rồi chạy trên t\n        Console.WriteLine(dem + \" \" + dau);\n    }\n}",hints:["Tính π của p. Chạy k trên t: khi t[i] ≠ p[k] thì lùi k = π[k − 1] (lặp), khớp thì k++.","Khi k = p.Length: một lần xuất hiện bắt đầu tại i − m + 1 (cộng 1 nữa vì đánh số từ 1); rồi k = π[k − 1] để đếm cả các lần chồng nhau.","Gọi IndexOf lặp lại từ từng vị trí cũng là so khớp trâu bò: O(|t| · |p|) trong trường hợp xấu."]}},{t:"Họa tiết lặp lại",d:"Một dải vải in họa tiết, đọc thành chuỗi s (chữ thường, 1 ≤ |s| ≤ 10^6). Tìm số d nhỏ nhất (1 ≤ d ≤ |s|) sao cho s[i] = s[i + d] với mọi i hợp lệ — độ dài của một họa tiết; dải vải có thể kết thúc giữa chừng một họa tiết. Đầu vào: dòng s. Đầu ra: d.",tests:[{in:"abcabcab",out:"3"},{in:"aaaa",out:"1"},{in:"abcd",out:"4"},{in:"a",out:"1"},{in:"abaababaab",out:"5"},{in:"aabaaab",out:"4"},{in:"abaababaababaababaababaababaababaababaababa",out:"5"},{in:"bbbbabbbaabaaabaaaaaaaaaabbaba",out:"30"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s;\n    cin >> s;\n    int n = s.size();\n    // chu kỳ nhỏ nhất = n − π[n − 1]\n    cout << n << \"\\n\";\n    return 0;\n}",perf:{gen:n=>"a".repeat(n-1)+"b",ns:[250,500,1000,2000],need:"n",limit:n=>40*n+300,why:"Thử từng chu kỳ d và so cả chuỗi tốn O(n²)."},py:{start:"s = input()\nn = len(s)\n# chu kỳ nhỏ nhất = n − π[n − 1]\nprint(n)",hints:["s có chu kỳ d ⇔ tiền tố độ dài n − d trùng hậu tố độ dài n − d.","Muốn d nhỏ nhất thì cần đoạn trùng dài nhất: π[n − 1]. Đáp án n − π[n − 1].","Thử từng d rồi so cả chuỗi tốn O(n²) với s = aaa…ab."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = Console.ReadLine();\n        int n = s.Length;\n        // chu kỳ nhỏ nhất = n − π[n − 1]\n        Console.WriteLine(n);\n    }\n}",hints:["s có chu kỳ d ⇔ tiền tố độ dài n − d trùng hậu tố độ dài n − d.","Muốn d nhỏ nhất thì cần đoạn trùng dài nhất: π[n − 1]. Đáp án n − π[n − 1].","Thử từng d rồi so cả chuỗi tốn O(n²) với s = aaa…ab."]}},{t:"Khóa số xoay vòng",d:"Một ổ khóa có vòng chữ a (chữ thường). Xoay trái k nấc biến a thành a[k..] + a[0..k − 1]. Cho hai chuỗi a, b cùng độ dài (1 ≤ |a| ≤ 10^6), in k nhỏ nhất (0 ≤ k < |a|) để xoay a thành b, hoặc −1 nếu không thể. Đầu vào: dòng a, dòng b. Đầu ra: k.",tests:[{in:"abcde\ncdeab",out:"2"},{in:"abcde\nabced",out:"-1"},{in:"aaaa\naaaa",out:"0"},{in:"abab\nbaba",out:"1"},{in:"x\nx",out:"0"},{in:"abcabc\ncabcab",out:"2"},{in:"babbabababbaabababab\nbabababbaababababbab",out:"3"},{in:"abaaaaabaaaabbabbaba\nabbabbabaabaaaaabaaa",out:"11"},{in:"bbaaaabbaabaaaa\naabbabbababbbab",out:"-1"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string a, b;\n    cin >> a >> b;\n    // b là phép xoay của a ⇔ b xuất hiện trong a + a\n    cout << -1 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>"a".repeat(n-1)+"b"+"\n"+"a".repeat(n),ns:[250,500,1000,2000],need:"n",limit:n=>80*n+300,why:"Thử từng k rồi so cả chuỗi tốn O(n²)."},py:{start:"a = input()\nb = input()\n# b là phép xoay của a ⇔ b xuất hiện trong a + a\nprint(-1)",hints:["b là phép xoay trái k nấc của a ⇔ b xuất hiện trong a + a tại vị trí k.","Tìm lần xuất hiện đầu tiên của b trong a + a (chỉ xét k < len(a)) bằng Z-function của b + '#' + a + a, hoặc KMP.","Thử từng k rồi so a[k:] + a[:k] == b tốn O(n²)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string a = Console.ReadLine(), b = Console.ReadLine();\n        // b là phép xoay của a ⇔ b xuất hiện trong a + a\n        Console.WriteLine(-1);\n    }\n}",hints:["b là phép xoay trái k nấc của a ⇔ b xuất hiện trong a + a tại vị trí k.","Tìm lần xuất hiện đầu tiên của b trong a + a (chỉ xét k < n) bằng Z-function của b + '#' + a + a, hoặc KMP.","Thử từng k rồi so cả chuỗi tốn O(n²)."]}}]);

makeQuiz("quiz68","score68",[{"q": "π[i] (hàm tiền tố) là gì?", "o": ["Số lần s[i] xuất hiện", "Độ dài lớn nhất của tiền tố thật sự của s[0..i] cũng là hậu tố của nó", "Vị trí xuất hiện tiếp theo", "Độ dài chuỗi"], "a": 1, "e": "Ví dụ “aabaa”: π[4] = 2."}, {"q": "Khi KMP gặp ký tự không khớp sau khi đã khớp k ký tự, k trở thành?", "o": ["0", "k − 1", "π[k − 1] (rồi thử tiếp)", "k + 1"], "a": 2, "e": "Giữ lại phần dài nhất vẫn còn khớp."}, {"q": "Để tìm p trong t bằng Z-function, ta tính z của chuỗi nào?", "o": ["t", "p", "p + '#' + t với '#' không có trong p, t", "t + p"], "a": 2, "e": "Vị trí có z = |p| là một lần xuất hiện."}, {"q": "Độ phức tạp của KMP với |t| = n, |p| = m?", "o": ["O(n · m)", "O(n + m)", "O(n log m)", "O(m²)"], "a": 1, "e": "Con trỏ trên văn bản không bao giờ lùi."}]);

